/*
 * Shared test-group runner.
 *
 * The group list lives here, and only here, so that every driver runs exactly
 * the same corpus:
 *
 *   - main.c     the C driver, and what CTest invokes
 *   - c-tests/   the Rust driver, which calls sr_run_test_group()
 *
 * main() deliberately lives in main.c so this file can be linked into the Rust
 * test binary, which brings its own entry point.
 */

#include <stdio.h>

#include "unity_fixture.h"

/* Each generated by TEST_GROUP_RUNNER() in the corresponding test file. */
extern void RunTestGroup_LegacyApi(void);
extern void RunTestGroup_Auth(void);
extern void RunTestGroup_Connection(void);
extern void RunTestGroup_CRUD(void);
extern void RunTestGroup_Geometry(void);
extern void RunTestGroup_IO(void);
extern void RunTestGroup_Memory(void);
extern void RunTestGroup_Object(void);
extern void RunTestGroup_Options(void);
extern void RunTestGroup_Query(void);
extern void RunTestGroup_RPC(void);
extern void RunTestGroup_Session(void);
extern void RunTestGroup_Stream(void);
extern void RunTestGroup_Transaction(void);
extern void RunTestGroup_Utility(void);
extern void RunTestGroup_ValueTypes(void);
extern void RunTestGroup_Variable(void);

void sr_run_all_test_groups(void)
{
    RUN_TEST_GROUP(LegacyApi);
    RUN_TEST_GROUP(Auth);
    RUN_TEST_GROUP(Connection);
    RUN_TEST_GROUP(CRUD);
    RUN_TEST_GROUP(Geometry);
    RUN_TEST_GROUP(IO);
    RUN_TEST_GROUP(Memory);
    RUN_TEST_GROUP(Object);
    RUN_TEST_GROUP(Options);
    RUN_TEST_GROUP(Query);
    RUN_TEST_GROUP(RPC);
    RUN_TEST_GROUP(Session);
    RUN_TEST_GROUP(Stream);
    RUN_TEST_GROUP(Transaction);
    RUN_TEST_GROUP(Utility);
    RUN_TEST_GROUP(ValueTypes);
    RUN_TEST_GROUP(Variable);
}

/*
 * Run a single group and return the number of failures.
 *
 * Unity Fixture filters when each test is dispatched rather than when the group
 * runner is called, so passing "-g <group>" and then running every group
 * executes only the matching one. The match is strstr(), so no group name may
 * contain another; CMake and this file both assert that.
 */
int sr_run_test_group(const char *group)
{
    const char *argv[] = {"surrealdb_c_tests", "-g", group, "-v"};
    int failures = UnityMain(4, argv, sr_run_all_test_groups);

    if (failures != 0)
    {
        return failures;
    }

    /*
     * A filter that matches nothing runs no tests and reports no failures,
     * so a renamed or misspelled group would silently look like a pass.
     */
    if (Unity.NumberOfTests == 0)
    {
        fprintf(stderr, "no tests matched group '%s'\n", group);
        return -1;
    }

    return 0;
}
